-- ===== A201-01 =====
-- nitrifikation_gefordert
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Bemessungswerten $\mathrm{A}_{\mathrm{EW}} \geq 15 \mathrm{~m}^{2} / \mathrm{E}$ ist im Sommer eine teilweise Nitrifikation festzustellen, wobei ein Teil des gebildeten Nitrats denitrifiziert wird. | Bei den angegebenen Bemessungswerten ist die Nitrifikation gering. Wird sie gefordert, können belüftete Abwasserteiche, z. B. mit integrierten Festbetteinrichtungen, kombiniert werden. — printed p.10 and p.11', verification_note='md-verified 2026-09-05 (§5.3, §5.4, printed p.10 and p.11) [VC]', verified_at=now() where id='5a5627f7-860c-4ad4-bb28-d24c08bc82d1' and verification_status not in ('verified_against_standard','corrected');
-- groessenklasse
update public.fields set verification_status='verified_against_standard', verification_quote='Mit Ausnahme von Schönungsteichen überschreiten diese Anlagen in der Regel nicht die Größenklasse 2 gemäß Anhang 1 der Abwasserverordnung, d. h. den Ausbauwert EW ${ }_{\text {BSB } 5}=5000$ E. Darauf sind die Bemessungswerte in diesem Arbeitsblatt abgestellt. — printed p.6', verification_note='md-verified 2026-09-05 (§1, printed p.6) [VC]', verified_at=now() where id='a8bdf156-b1ad-4781-bdfc-22113e05355d' and verification_status not in ('verified_against_standard','corrected');
-- abwasser_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Die nachstehenden Regeln gelten für Abwasserteiche zur Behandlung überwiegend häuslichen Abwassers oder diesem vergleichbaren gewerblichen Abwassers. Abwasserteiche für industrielles Abwasser und Teiche mit Schlammrückführung werden in diesem Arbeitsblatt nicht behandelt. — printed p.6', verification_note='md-verified 2026-09-05 (§1, printed p.6) [VC]', verified_at=now() where id='3a22a6ca-1bb4-4a74-995b-8b811aca0bbf' and verification_status not in ('verified_against_standard','corrected');
