update public.fields set verification_status='verified_against_standard', verification_quote='Der Anwendungsbereich von Abwasserteichen kann auf Grund der verschiedenen Reinigungsvorgänge wie folgt gegliedert werden: | Absetzteiche: als Vorstufe vor einer weiteren Behandlung zur gezielten Abtrennung, Sammlung und Faulung von Schlamm; | Unbelüftete zur biologischen Behandlung von Teiche: Abwasser meist kleiner Ortschaften und Siedlungen; wegen des großen Flächenbedarfs liegt ihr Anwendungsbereich in der Regel bei Anschlusswerten unter $\mathrm{EW}_{\text {BSB } 5,60}=1000 \mathrm{E}$; — printed p.7', verification_note='md-verified 2026-09-05 (§3, printed p.7) [VC] — caveat: the enum also carries Nachklaerteich (§5.5) and Schoenungsteich (§4.5), which the quoted §3 list continues beyond the cited run', verified_at=now() where id='2b44aa66-9321-487d-92c8-47333ebb327e' and verification_status not in ('verified_against_standard','corrected');
