-- kanalisationsart
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Mischwasserentlastung ist der Nachweis zu führen, dass die Anforderungen des ATV-A 128 eingehalten werden. In der Regel kommen folgende drei Fälle zur Anwendung: | Bei Teichen hinter einer Trennkanalisation, insbesondere mit wenig Fremdwasser, kann im Sommer durch Verdunstung eine Aufkonzentrierung der Inhaltsstoffe erfolgen. Zeitweilig kann ein Abfluss ausbleiben. — printed p.15 and p.8', verification_note='md-verified 2026-09-05 (§6, §4.2, printed p.15 and p.8) [VC]', verified_at=now() where id='0de73799-fd85-4dcb-b454-1dc984586bbd' and verification_status not in ('verified_against_standard','corrected');
-- bodenart
