-- grundwasserstand
update public.fields set verification_status='verified_against_standard', verification_quote='Die Teichdichtung dient dem Schutz des Grundwassers und der Verhinderung unzulässiger Verdünnung durch Zustrom von Grundwasser in die Teiche. Die auf die Aufenthaltszeit pro Becken bezogenen Anforderungen der DIN EN 12255-5 an die Wasserdichtheit beziehen sich auf den Trockenwetterabfluss. | Die Entleerung von Teichen darf nur bei ausreichend großem Abstand zwischen Teichsohle und Grundwasserspiegel erfolgen, da andernfalls die Dichtung beschädigt wird. — printed p.14 and p.17', verification_note='md-verified 2026-09-05 (§5.8, §8.1, printed p.14 and p.17) [VC]', verified_at=now() where id='18ef8aec-eb04-4e64-a0f5-63e1afb51613' and verification_status not in ('verified_against_standard','corrected');
-- mischwasser_fall_standort
update public.fields set verification_status='verified_against_standard', verification_quote='Im Fall I besteht eine Entlastungsmöglichkeit am Ortsende (Abb.: 2). | Der Ablauf ( $Q_{D r}$ ) aus dem RÜB durchfließt im Fall ll sämtliche Teiche hintereinander (Abb.: 3). | Sämtliches gesammeltes Mischwasser wird im Fall III unvermindert der Teichanlage zugeführt. Bei diesem Fall sind drei mögliche Betriebsweisen zu unterscheiden: — printed p.15', verification_note='md-verified 2026-09-05 (§6, printed p.15) [VC]', verified_at=now() where id='beeb43cd-2644-49b3-95c9-894df8dea4a9' and verification_status not in ('verified_against_standard','corrected');
