update public.fields set verification_status='verified_against_standard', verification_quote='Diese Kombinationslösung kommt für Ausbaugrößen zwischen mehreren hundert und etwa 3000 E zur Anwendung, wenn die Vorteile von Teichanlagen genutzt werden sollen, jedoch die dafür insgesamt erforderlichen großen Flächen nicht zur Verfügung stehen oder bei Teichanlagen auch Nitrifikation gefordert wird. — printed p.7', verification_note='md-verified 2026-09-05 (§3, printed p.7) [VC] — duplicate of A201-02.A_verfuegbar (flagged in the STAGED file)', verified_at=now() where id='80c1dad8-b2bd-4cdd-9106-277c51234dd5' and verification_status not in ('verified_against_standard','corrected');
-- vorfluter_empfindlichkeit
update public.fields set verification_status='verified_against_standard', verification_quote='Bei leistungsschwachen Gewässern oder besonders hohen Ansprüchen an die Gewässergüte sind Schönungsteiche ein einfaches und zuverlässiges | Verfahren, um den Ablauf einer biologischen Kläranlage hinsichtlich der Schwebstoffe, organischer Restbelastung, anorganischer Nährstoffe und hygienischer Beschaffenheit zu verbessern. Ihr Pufferungsvermögen bewirkt einen Konzentrationsausgleich. Sie werden in der Regel ohne künstliche Belüftung betrieben. — printed p.9', verification_note='md-verified 2026-09-05 (§4.5, printed p.9) [VC] — the three-step enum granularity (gering/mittel/hoch) is the EKOWAI encoding; the source names only "leistungsschwache Gewaesser oder besonders hohe Ansprueche"', verified_at=now() where id='40d67876-05ff-4cc9-b354-0c4d8f06bc0a' and verification_status not in ('verified_against_standard','corrected');
