-- F-06  t_R_absetz >= 1
update public.equations set verification_status='verified_against_standard', verification_quote='Es muss eine Durchflusszeit von mindestens einem Tag bei Trockenwetter eingehalten werden. Dies gilt auch bei hohen Fremdwasserzuflüssen. — printed p.10', verification_note='md-verified 2026-09-05 (§5.2, printed p.10) [VC]', verified_at=now() where id='ba340cbf-9420-410d-bfc9-d4380dde9a6e' and verification_status <> 'verified_against_standard';
-- F-07  A_EW_unbelueftet >= 10
update public.equations set verification_status='verified_against_standard', verification_quote='Unbelüftete Abwasserteiche sind mit $A_{E W} \geq 10 \mathrm{~m}^{2} / \mathrm{E}$ zu bemessen. Dieser Wert kann auf $8 \mathrm{~m}^{2} / \mathrm{E}$ vermindert werden, wenn nach Abschnitt 5.2 bemessene Absetzteiche vorgeschaltet sind. — printed p.10', verification_note='md-verified 2026-09-05 (§5.3, printed p.10) [VC]', verified_at=now() where id='2c9d5018-004f-4f67-b40b-dcc8898d3171' and verification_status <> 'verified_against_standard';
-- F-08  A_EW_unbelueftet >= 8
