-- F-09  A_EW_Mi = 5
update public.equations set verification_status='verified_against_standard', verification_quote='Zur Regenwasserbehandlung ist ein Zuschlag von $\mathrm{A}_{\mathrm{Ew}, \mathrm{MI}}=5 \mathrm{~m}^{2} / \mathrm{E}$ auf beide vorgenannten Bemessungswerte erforderlich (siehe Abschnitt 6). — printed p.10', verification_note='md-verified 2026-09-05 (§5.3, printed p.10) [VC]', verified_at=now() where id='907ca435-b41e-43f9-8811-ea85b6098956' and verification_status <> 'verified_against_standard';
-- F-10  A_EW_nitrifikation >= 15
update public.equations set verification_status='verified_against_standard', verification_quote='Bei Bemessungswerten $\mathrm{A}_{\mathrm{EW}} \geq 15 \mathrm{~m}^{2} / \mathrm{E}$ ist im Sommer eine teilweise Nitrifikation festzustellen, wobei ein Teil des gebildeten Nitrats denitrifiziert wird. — printed p.10', verification_note='md-verified 2026-09-05 (§5.3, printed p.10) [VC]', verified_at=now() where id='a69cfcaf-18a2-482e-a359-63848ffa00b9' and verification_status <> 'verified_against_standard';
-- F-11  B_R_BSB <= 25
update public.equations set verification_status='verified_against_standard', verification_quote='Für die Bemessung von belüfteten Abwasserteichen muss eine $\mathrm{BSB}_{5}$-Raumbelastung von $B_{R, B S B} \leq 25 \mathrm{~g} /\left(\mathrm{m}^{3} \cdot \mathrm{~d}\right)$ angesetzt werden. — printed p.11', verification_note='md-verified 2026-09-05 (§5.4, printed p.11) [VC]', verified_at=now() where id='2aa30964-75b6-4990-995e-58d16598fc2c' and verification_status <> 'verified_against_standard';
-- F-12  t_R_belueftet >= 5
update public.equations set verification_status='verified_against_standard', verification_quote='Es muss eine Durchflusszeit von fünf Tagen bei Trockenwetter eingehalten werden. — printed p.11', verification_note='md-verified 2026-09-05 (§5.4, printed p.11) [VC]', verified_at=now() where id='c34e9132-0c2f-404a-bc06-c2673770c761' and verification_status <> 'verified_against_standard';
-- F-13  OV_C_BSB >= 1.5
update public.equations set verification_status='verified_against_standard', verification_quote='Als Sauerstoffverbrauch muss $\mathrm{OV}_{\mathrm{C}, \mathrm{BSB}} \geq 1,5 \mathrm{~kg} / \mathrm{kg}$ und für die Umwälzung, je nach eingesetztem System und hydraulischer Gestaltung des Teiches, eine Leistungsdichte $\mathrm{P}_{\mathrm{R}}=1-3 \mathrm{~W} / \mathrm{m}^{3}$ angesetzt werden. Die Sauerstoffzufuhr sollte an die Belastung angepasst werden können. — printed p.11', verification_note='md-verified 2026-09-05 (§5.4, printed p.11) [VC]', verified_at=now() where id='74018e72-ea91-4a1e-bef9-2cb4f3782f8d' and verification_status <> 'verified_against_standard';
-- F-14  P_R between 1 and 3
