-- F-15  t_R_nachklaer >= 1
update public.equations set verification_status='verified_against_standard', verification_quote='Das erforderliche gesamte Teichvolumen errechnet sich aus der erforderlichen Mindestdurchflusszeit $t_{R}=1 d$, bezogen auf den maximalen Zufluss zuzüglich dem Volumenanteil für die notwendige Schlammspeicherung bis zur Räumung. — printed p.11', verification_note='md-verified 2026-09-05 (§5.5, printed p.11) [VC]', verified_at=now() where id='05bc3636-53d6-4518-aa00-2f40fce08d5a' and verification_status <> 'verified_against_standard';
